# builder/gen_ch19_p1.py
# -*- coding: utf-8 -*-

exercises = [{'num': 1, 'title': 'Динамическое переключение уровня логирования на лету через slog.LevelVar', 'task': '**Динамический уровень логов**: В проде нельзя просто перезапустить сервер, чтобы включить `Debug`. Создай переменную `var logLevel = new(slog.LevelVar)`. Настрой логгер с ней. Напиши HTTP-хендлер `PUT /loglevel`, который принимает JSON `{"level": "DEBUG"}` и меняет уровень "на лету" через `logLevel.Set(slog.LevelDebug)`.', 'theory': '`slog.LevelVar` — потокобезопасная переменная уровня логирования (атомарное значение). Она реализует интерфейс `slog.Leveler`. При передаче `&levelVar` в опции хендлера `slog.HandlerOptions{Level: levelVar}` изменение уровня через `levelVar.Set(...)` мгновенно активирует новые уровни логирования во всех горутинах без блокировок и перезапуска процесса.', 'step_by_step': '1. Создадим глобальный или контекстный `logLevel := new(slog.LevelVar)` (по умолчанию `slog.LevelInfo`).\n2. Инициализируем `slog.New(slog.NewJSONHandler(os.Stdout, &slog.HandlerOptions{Level: logLevel}))`.\n3. Реализуем HTTP-хендлер `handleSetLogLevel`, парсящий JSON и вызывающий `logLevel.Set(...)`.\n4. В `main` сымитируем HTTP-запрос на смену уровня с INFO на DEBUG и проверим вывод.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"bytes"\n\t"encoding/json"\n\t"fmt"\n\t"log/slog"\n\t"net/http"\n\t"net/http/httptest"\n\t"os"\n\t"strings"\n)\n\nvar logLevel = new(slog.LevelVar) // По умолчанию LevelInfo (0)\n\ntype LevelRequest struct {\n\tLevel string `json:"level"`\n}\n\nfunc logLevelHandler(w http.ResponseWriter, r *http.Request) {\n\tif r.Method != http.MethodPut {\n\t\thttp.Error(w, "Method not allowed", http.StatusMethodNotAllowed)\n\t\treturn\n\t}\n\n\tvar req LevelRequest\n\tif err := json.NewDecoder(r.Body).Decode(&req); err != nil {\n\t\thttp.Error(w, err.Error(), http.StatusBadRequest)\n\t\treturn\n\t}\n\n\tswitch strings.ToUpper(req.Level) {\n\tcase "DEBUG":\n\t\tlogLevel.Set(slog.LevelDebug)\n\tcase "INFO":\n\t\tlogLevel.Set(slog.LevelInfo)\n\tcase "WARN":\n\t\tlogLevel.Set(slog.LevelWarn)\n\tcase "ERROR":\n\t\tlogLevel.Set(slog.LevelError)\n\tdefault:\n\t\thttp.Error(w, "Unknown level", http.StatusBadRequest)\n\t\treturn\n\t}\n\n\tslog.Info("Уровень логирования успешно изменен", "new_level", logLevel.Level().String())\n\tw.WriteHeader(http.StatusOK)\n\t_, _ = w.Write([]byte(`{"status":"ok"}`))\n}\n\nfunc main() {\n\t// 1. Инициализация JSON-логгера с динамическим LevelVar\n\thandler := slog.NewJSONHandler(os.Stdout, &slog.HandlerOptions{Level: logLevel})\n\tlogger := slog.New(handler)\n\tslog.SetDefault(logger)\n\n\tfmt.Println("--- 1. Начальное состояние (LevelInfo) ---")\n\tslog.Debug("Этот Debug-лог НЕ будет напечатан")\n\tslog.Info("Сервер запущен в рабочем режиме")\n\n\t// 2. Имитация вызова PUT /loglevel с телом {"level": "DEBUG"}\n\tfmt.Println("\\n--- 2. Динамическое переключение на DEBUG через HTTP ---")\n\tbody := bytes.NewBufferString(`{"level": "DEBUG"}`)\n\treq := httptest.NewRequest(http.MethodPut, "/loglevel", body)\n\trec := httptest.NewRecorder()\n\n\tlogLevelHandler(rec, req)\n\n\t// 3. Проверка после переключения\n\tfmt.Println("\\n--- 3. После переключения (LevelDebug) ---")\n\tslog.Debug("Диагностический лог: подробное состояние кэша", "cache_keys", 450)\n\tslog.Info("Запрос успешно обработан")\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# --- 1. Начальное состояние (LevelInfo) ---\n# {"time":"2026-09-02T18:40:00Z","level":"INFO","msg":"Сервер запущен в рабочем режиме"}\n# \n# --- 2. Динамическое переключение на DEBUG через HTTP ---\n# {"time":"2026-09-02T18:40:00Z","level":"INFO","msg":"Уровень логирования успешно изменен","new_level":"DEBUG"}\n# \n# --- 3. После переключения (LevelDebug) ---\n# {"time":"2026-09-02T18:40:00Z","level":"DEBUG","msg":"Диагностический лог: подробное состояние кэша","cache_keys":450}\n# {"time":"2026-09-02T18:40:00Z","level":"INFO","msg":"Запрос успешно обработан"}'}], 'under_the_hood': '`slog.LevelVar` использует `sync/atomic.Int64` внутри. Метод `Enabled(ctx, level)` вызывается перед форматированием атрибутов, поэтому при выключенном `Debug` не происходит аллокаций памяти под аргументы лога.', 'pitfalls': 'Если передать в `slog.HandlerOptions{Level: slog.LevelInfo}` обычное значение, а не указатель `*slog.LevelVar`, динамическое изменение будет невозможно.', 'bigtech_interview': '**Вопрос с собеседования:** «Как в Kubernetes микросервисах динамически включать Debug-логи без рестарта подов?»\n**Ответ:** 1) Через защищенный админ-эндпоинт `PUT /admin/loglevel` (с mTLS/RBAC авторизацией). 2) Через подписку на ConfigMap в etcd / Consul или перехват сигнала ОС `SIGUSR1`.'}, {'num': 2, 'title': 'Структурированное логирование в формате JSON с полями time, level, msg', 'task': 'Установите и настройте структурированный логгер `zerolog` или `log/slog`. Выведите JSON-логи в stdout с полями `level`, `msg`, `time`.', 'theory': 'Структурированное логирование (Structured Logging) форматирует каждую запись как валидный JSON-объект. Это стандарт для современных Cloud-Native сред (Kubernetes, AWS CloudWatch, ELK, Grafana Loki), позволяющий индексировать и фильтровать логи по полям без медленных регулярных выражений.', 'step_by_step': '1. Создадим `slog.NewJSONHandler(os.Stdout, nil)`.\n2. Обернем в `slog.New(handler)`.\n3. Запишем информационный и предупреждающий логи с атрибутами `user_id`, `ip`, `latency_ms`.\n4. В `main` убедимся в валидности выводимого JSON.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"log/slog"\n\t"os"\n\t"time"\n)\n\nfunc main() {\n\t// Создание JSON-хендлера, пишущего в стандартный вывод\n\thandler := slog.NewJSONHandler(os.Stdout, nil)\n\tlogger := slog.New(handler)\n\n\t// Запись структурированных логов с типизированными атрибутами\n\tlogger.Info("Входящее HTTP-соединение",\n\t\tslog.String("method", "GET"),\n\t\tslog.String("path", "/api/v1/users"),\n\t\tslog.Int("status", 200),\n\t\tslog.Duration("latency", 12*time.Millisecond),\n\t)\n\n\tlogger.Warn("Превышение порога потребления памяти",\n\t\tslog.Float64("memory_used_mb", 850.5),\n\t\tslog.Float64("memory_limit_mb", 1024.0),\n\t)\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# {"time":"2026-09-02T18:40:00Z","level":"INFO","msg":"Входящее HTTP-соединение","method":"GET","path":"/api/v1/users","status":200,"latency":12000000}\n# {"time":"2026-09-02T18:40:00Z","level":"WARN","msg":"Превышение порога потребления памяти","memory_used_mb":850.5,"memory_limit_mb":1024}'}], 'under_the_hood': '`slog.JSONHandler` сериализует ключи и значения напрямую в кольцевой байтовый буфер без рефлексии для базовых типов (`slog.String`, `slog.Int`, `slog.Float64`), обеспечивая скорость работы близкую к `zerolog` и `zap`.', 'pitfalls': 'Не используйте неструктурированную склейку строк `fmt.Sprintf` внутри `msg` — все динамические параметры должны передаваться как отдельные атрибуты `key/value`.', 'bigtech_interview': '**Вопрос с собеседования:** «Почему в HighLoad бэкендах запрещены текстовые логи вроде log.Printf("user %d logged in", id)?»\n**Ответ:** Текстовые логи требуют ресурсоемкого полнотекстового поиска (Full-Text Search) в Elasticsearch/Loki. JSON-логи мгновенно парсятся и фильтруются по числовым и строковым индексам `user.id: 42 AND status: 500` с минимальной нагрузкой на кластер мониторинга.'}, {'num': 3, 'title': 'Маскирование персональных данных (PII) через ReplaceAttr в slog', 'task': 'Настройте глобальный `slog.Logger` с `JSONHandler` и `ReplaceAttr` для маскировки PII-данных (email, телефон, password → `***`).', 'theory': 'Функция `ReplaceAttr` в `slog.HandlerOptions` перехватывает каждый атрибут перед записью. Это позволяет централизованно маскировать персональные данные (Personally Identifiable Information — PII) в соответствии с законами о защите персональных данных (152-ФЗ, GDPR, PCI-DSS).', 'step_by_step': '1. Объявим функцию `sanitizeAttrs(groups []string, a slog.Attr) slog.Attr`.\n2. Проверим ключ `a.Key`: для `password`, `email`, `phone`, `card_number` заменим значение на `"***"`.\n3. Инициализируем `slog.NewJSONHandler` с этой опцией.\n4. В `main` вызовем логирование и убедимся, что секреты скрыты.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"log/slog"\n\t"os"\n\t"strings"\n)\n\nfunc sanitizePII(groups []string, a slog.Attr) slog.Attr {\n\t// Список конфиденциальных ключей для маскирования\n\tswitch strings.ToLower(a.Key) {\n\tcase "password", "token", "secret", "cvv":\n\t\treturn slog.String(a.Key, "[REDACTED]")\n\tcase "email":\n\t\t// Частичное маскирование email: a***@corp.ru\n\t\temailStr := a.Value.String()\n\t\tif parts := strings.Split(emailStr, "@"); len(parts) == 2 && len(parts[0]) > 0 {\n\t\t\tmasked := string(parts[0][0]) + "***@" + parts[1]\n\t\t\treturn slog.String(a.Key, masked)\n\t\t}\n\t\treturn slog.String(a.Key, "***@***")\n\tcase "phone":\n\t\treturn slog.String(a.Key, "+7-***-***-**-99")\n\t}\n\treturn a\n}\n\nfunc main() {\n\topts := &slog.HandlerOptions{\n\t\tReplaceAttr: sanitizePII,\n\t}\n\thandler := slog.NewJSONHandler(os.Stdout, opts)\n\tlogger := slog.New(handler)\n\tslog.SetDefault(logger)\n\n\tslog.Info("Регистрация нового пользователя",\n\t\tslog.String("username", "alex_dev"),\n\t\tslog.String("email", "alexander.ivanov@company.ru"),\n\t\tslog.String("phone", "+79991234599"),\n\t\tslog.String("password", "SuperSecretP@ss123"),\n\t)\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# {"time":"2026-09-02T18:40:00Z","level":"INFO","msg":"Регистрация нового пользователя","username":"alex_dev","email":"a***@company.ru","phone":"+7-***-***-**-99","password":"[REDACTED]"}'}], 'under_the_hood': '`ReplaceAttr` вызывается на этапе обхода дерева атрибутов. Если вернуть пустой атрибут `slog.Attr{}`, поле будет полностью удалено из итогового JSON.', 'pitfalls': '`ReplaceAttr` проверяет только имена ключей первого уровня, если не учитывать срез `groups` для вложенных структур.', 'bigtech_interview': '**Вопрос с собеседования:** «Как удалить ключ time или level из вывода slog через ReplaceAttr?»\n**Ответ:** Проверить `if a.Key == slog.TimeKey { return slog.Attr{} }`. Возврат нулевой структуры `slog.Attr{}` полностью удаляет встроенное поле из JSON.'}, {'num': 4, 'title': 'Иерархическая группировка атрибутов через slog.Group и slog.Attr', 'task': 'Используйте `slog.Attr` и `slog.Group` для создания вложенных структур в логах (например, `"request": {"method": "GET", "path": "/api"}`).', 'theory': '`slog.Group(key, attrs...)` объединяет группу атрибутов во вложенный JSON-объект. Это структурирует логи сложных подсистем (HTTP-запрос, метаданные клиента, параметры БД).', 'step_by_step': '1. Создадим JSON-логгер.\n2. Сформируем группу `"http_request"` с полями `method`, `path`, `status`.\n3. Сформируем группу `"client"` с полями `ip`, `geo`.\n4. Выведем лог через `logger.Info`.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"log/slog"\n\t"os"\n)\n\nfunc main() {\n\tlogger := slog.New(slog.NewJSONHandler(os.Stdout, nil))\n\n\t// Логирование с вложенными группами\n\tlogger.Info("Обработан входящий платеж",\n\t\tslog.Int("order_id", 99482),\n\t\tslog.Group("http",\n\t\t\tslog.String("method", "POST"),\n\t\t\tslog.String("path", "/api/v2/checkout"),\n\t\t\tslog.Int("status_code", 200),\n\t\t),\n\t\tslog.Group("geo_client",\n\t\t\tslog.String("ip", "195.201.45.12"),\n\t\t\tslog.String("country", "RU"),\n\t\t\tslog.String("city", "Moscow"),\n\t\t),\n\t)\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# {"time":"2026-09-02T18:40:00Z","level":"INFO","msg":"Обработан входящий платеж","order_id":99482,"http":{"method":"POST","path":"/api/v2/checkout","status_code":200},"geo_client":{"ip":"195.201.45.12","country":"RU","city":"Moscow"}}'}], 'under_the_hood': '`slog.Group` открывает новый фигурный блок `{` в JSON-буфере и рекурсивно сериализует дочерние атрибуты с префиксом группы.', 'pitfalls': 'Пустая группа `slog.Group("empty")` без дочерних атрибутов будет полностью опущена в выводе.', 'bigtech_interview': '**Вопрос с собеседования:** «В чем отличие slog.Group("req", ...) от logger.WithGroup("req")?»\n**Ответ:** `slog.Group` оборачивает во вложенный объект только конкретные атрибуты одного вызова лога. `logger.WithGroup` возвращает новый дочерний логгер, у которого **все последующие** логи и добавленные атрибуты навсегда будут помещены внутрь указанной группы.'}, {'num': 5, 'title': 'HTTP Middleware с автоматической трассировкой request_id через logger.With', 'task': 'Реализуйте middleware, который добавляет `request_id` (UUID) в контекст и автоматически пробрасывает его во все логи через `slog.Logger.With("request_id", id)`.', 'theory': 'Дочерний логгер, созданный через `logger.With("request_id", id)`, сохраняет этот атрибут во всех последующих записях. Сохранение логгера в `context.Context` гарантирует доступ к сквозному идентификатору запроса во всех слоях бизнес-логики.', 'step_by_step': '1. Определим кастомный ключ контекста `type ctxKey struct{}`.\n2. Напишем middleware `RequestIDMiddleware(logger *slog.Logger) func(http.Handler) http.Handler`.\n3. В хендлере извлечем логгер из контекста и запишем лог.\n4. В `main` протестируем выполнение запроса.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"context"\n\t"fmt"\n\t"log/slog"\n\t"net/http"\n\t"net/http/httptest"\n\t"os"\n)\n\ntype loggerKey struct{}\n\n// Middleware обогащает логгер уникальным request_id и сохраняет в контекст\nfunc RequestIDMiddleware(baseLogger *slog.Logger) func(http.Handler) http.Handler {\n\treturn func(next http.Handler) http.Handler {\n\t\treturn http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {\n\t\t\treqID := r.Header.Get("X-Request-ID")\n\t\t\tif reqID == "" {\n\t\t\t\treqID = "req-uuid-9847192" // Генерация UUID\n\t\t\t}\n\n\t\t\t// Создаем дочерний логгер с зафиксированным request_id\n\t\t\treqLogger := baseLogger.With(slog.String("request_id", reqID))\n\t\t\tctx := context.WithValue(r.Context(), loggerKey{}, reqLogger)\n\n\t\t\tw.Header().Set("X-Request-ID", reqID)\n\t\t\tnext.ServeHTTP(w, r.WithContext(ctx))\n\t\t})\n\t}\n}\n\n// Хелпер для извлечения логгера из контекста\nfunc FromContext(ctx context.Context) *slog.Logger {\n\tif l, ok := ctx.Value(loggerKey{}).(*slog.Logger); ok {\n\t\treturn l\n\t}\n\treturn slog.Default()\n}\n\nfunc orderHandler(w http.ResponseWriter, r *http.Request) {\n\tlogger := FromContext(r.Context())\n\tlogger.Info("Проверка остатков товара на складе", "item_id", "SKU-5501")\n\tlogger.Info("Платеж успешно авторизован", "amount_rub", 4500)\n\tw.WriteHeader(http.StatusOK)\n}\n\nfunc main() {\n\tbaseLogger := slog.New(slog.NewJSONHandler(os.Stdout, nil))\n\tmw := RequestIDMiddleware(baseLogger)\n\n\thandler := mw(http.HandlerFunc(orderHandler))\n\n\treq := httptest.NewRequest(http.MethodGet, "/order/checkout", nil)\n\treq.Header.Set("X-Request-ID", "trace-777-abc-999")\n\trec := httptest.NewRecorder()\n\n\tfmt.Println("--- Логирование с автоматическим request_id ---")\n\thandler.ServeHTTP(rec, req)\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# --- Логирование с автоматическим request_id ---\n# {"time":"2026-09-02T18:40:00Z","level":"INFO","msg":"Проверка остатков товара на складе","request_id":"trace-777-abc-999","item_id":"SKU-5501"}\n# {"time":"2026-09-02T18:40:00Z","level":"INFO","msg":"Платеж успешно авторизован","request_id":"trace-777-abc-999","amount_rub":4500}'}], 'under_the_hood': '`logger.With` предварительно кодирует добавленные атрибуты в байтовый префикс, поэтому при каждом последующем `logger.Info` эти поля подставляются без повторной сериализации.', 'pitfalls': 'Используйте пустую неэкспортируемую структуру `type loggerKey struct{}` вместо строки `"logger"`, чтобы избежать коллизий ключей контекста с другими библиотеками.', 'bigtech_interview': '**Вопрос с собеседования:** «Почему передавать логгер через context.Context лучше, чем глобальный slog.Default()?»\n**Ответ:** Потому что контекстный логгер автоматически содержит метаданные текущего потока (`request_id`, `user_id`, `trace_id`). Это делает функции независимыми от глобального состояния и упрощает юнит-тестирование с подменой логгера на мок.'}, {'num': 6, 'title': 'Управление порогами фильтрации через slog.HandlerOptions{Level: slog.LevelDebug}', 'task': 'Измени уровень логирования на `Debug` через `slog.HandlerOptions{Level: slog.LevelDebug}`. Убедись, что `slog.Debug` теперь выводится, а по умолчанию (LevelInfo) — нет.', 'theory': 'По умолчанию `slog` работает на уровне `LevelInfo` (значение `0`). Сообщения `LevelDebug` (`-4`) игнорируются. Для включения детальной отладки необходимо явно передать `slog.LevelDebug` в опциях хендлера.', 'step_by_step': '1. Создадим логгер с `LevelInfo` и проверим, что `Debug` не печатается.\n2. Создадим логгер с `slog.HandlerOptions{Level: slog.LevelDebug}`.\n3. Вызовем `Debug`, `Info`, `Warn`, `Error`.\n4. В `main` сравним вывод обоих логгеров.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"fmt"\n\t"log/slog"\n\t"os"\n)\n\nfunc main() {\n\t// 1. Стандартный логгер (LevelInfo по умолчанию)\n\tdefaultLogger := slog.New(slog.NewTextHandler(os.Stdout, nil))\n\tfmt.Println("=== Логгер по умолчанию (LevelInfo) ===")\n\tdefaultLogger.Debug("Скрытый Debug-лог 1")\n\tdefaultLogger.Info("Информационный лог 1")\n\n\t// 2. Логгер с включенным LevelDebug\n\tdebugOpts := &slog.HandlerOptions{\n\t\tLevel: slog.LevelDebug,\n\t}\n\tdebugLogger := slog.New(slog.NewTextHandler(os.Stdout, debugOpts))\n\tfmt.Println("\\n=== Логгер с LevelDebug ===")\n\tdebugLogger.Debug("Детальный Debug-лог 2", "sql_query", "SELECT * FROM orders WHERE id = 10")\n\tdebugLogger.Info("Информационный лог 2")\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# === Логгер по умолчанию (LevelInfo) ===\n# time=2026-09-02T18:40:00.000Z level=INFO msg="Информационный лог 1"\n# \n# === Логгер с LevelDebug ===\n# time=2026-09-02T18:40:00.000Z level=DEBUG msg="Детальный Debug-лог 2" sql_query="SELECT * FROM orders WHERE id = 10"\n# time=2026-09-02T18:40:00.000Z level=INFO msg="Информационный лог 2" '}], 'under_the_hood': 'Числовые значения уровней в `slog`: `LevelDebug = -4`, `LevelInfo = 0`, `LevelWarn = 4`, `LevelError = 8`. Метод `Enabled` проверяет `msgLevel >= handlerLevel`.', 'pitfalls': 'Шаг между стандартными уровнями равен 4, что позволяет создавать кастомные подуровни (например `LevelTrace = LevelDebug - 4`).', 'bigtech_interview': '**Вопрос с собеседования:** «Почему в Go slog уровни логирования представлены числами -4, 0, 4, 8?»\n**Ответ:** Разница в 4 единицы между уровнями заложена авторами Go специально для того, чтобы разработчики могли объявлять пользовательские промежуточные уровни логирования (`LevelDebug + 1`, `LevelNotice = LevelInfo + 2`) без изменения стандартных констант.'}, {'num': 7, 'title': 'Интерфейс slog.LogValuer для кастомного маскирования структур', 'task': '**Маскирование чувствительных данных**: Логировать пароли или номера карт — преступление. Создай структуру `User{Email, Password}`. Реализуй для неё интерфейс `slog.LogValuer` (метод `LogValue() slog.Value`), в котором поле `Password` заменяется на `"***"`. Передай структуру в `slog.Info` и проверь вывод.', 'theory': 'Интерфейс `slog.LogValuer` с методом `LogValue() slog.Value` позволяет типам самостоятельно контролировать, как именно они сериализуются в логи. Это обеспечивает 100% гарантию защиты от утечек секретов при передаче объекта в любой логгер.', 'step_by_step': '1. Объявим `type User struct { Email string; Password string; CardNumber string }`.\n2. Реализуем метод `(u User) LogValue() slog.Value`.\n3. Внутри метода вернем `slog.GroupValue(...)` с замаскированными полями.\n4. В `main` передадим структуру `User` в `slog.Info("создан пользователь", "user", u)`.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"log/slog"\n\t"os"\n)\n\ntype User struct {\n\tEmail      string\n\tPassword   string\n\tCardNumber string\n}\n\n// LogValue реализует интерфейс slog.LogValuer\nfunc (u User) LogValue() slog.Value {\n\treturn slog.GroupValue(\n\t\tslog.String("email", u.Email),\n\t\tslog.String("password", "********"),\n\t\tslog.String("card_number", "****-****-****-"+u.CardNumber[len(u.CardNumber)-4:]),\n\t)\n}\n\nfunc main() {\n\tlogger := slog.New(slog.NewJSONHandler(os.Stdout, nil))\n\n\tuser := User{\n\t\tEmail:      "cto@fintech.io",\n\t\tPassword:   "VerySecretPassword99!",\n\t\tCardNumber: "4276123456789876",\n\t}\n\n\t// Передаем весь объект напрямую в лог\n\tlogger.Info("Профиль пользователя обновлен", "user", user)\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# {"time":"2026-09-02T18:40:00Z","level":"INFO","msg":"Профиль пользователя обновлен","user":{"email":"cto@fintech.io","password":"********","card_number":"****-****-****-9876"}}'}], 'under_the_hood': '`slog` проверяет наличие метода `LogValue()` у переданного значения через утверждение типа интерфейса `slog.LogValuer` до начала сериализации в JSON.', 'pitfalls': 'Если объявить метод на указателе `(u *User) LogValue()`, а в лог передать структуру по значению `user` (не `&user`), интерфейс не сработает и секреты утекут! Реализуйте метод на значении `(u User)` или всегда передавайте указатель.', 'bigtech_interview': '**Вопрос с собеседования:** «В чем отличие slog.LogValuer от интерфейса fmt.Stringer?»\n**Ответ:** `fmt.Stringer` превращает весь объект в единую плоскую строку `string`. `slog.LogValuer` возвращает структурированный `slog.Value` (включая группы, списки и типизированные атрибуты), сохраняя JSON-схему лога.'}, {'num': 8, 'title': 'Маршрутизация логов: Error в файл, Info в stdout через составной Handler', 'task': 'Создайте `slog.Handler`, который записывает логи уровня `Error` и выше в отдельный файл (`error.log`), а `Info` — в `stdout`.', 'theory': 'Составной обработчик (Fork / Split Handler) разделяет поток записей: стандартные информационные логи идут в `stdout` контейнера, а критические ошибки дублируются в постоянный файл на диске или отдельный сервис алертинга.', 'step_by_step': '1. Создадим структуру `SplitHandler struct { infoHandler, errHandler slog.Handler }`.\n2. Реализуем методы интерфейса `slog.Handler`: `Enabled`, `Handle`, `WithAttrs`, `WithGroup`.\n3. В `Handle(ctx, r)` отправляем все логи в `infoHandler`, а при `r.Level >= slog.LevelError` — также в `errHandler`.\n4. В `main` проверим запись в консоль и в файл `error.log`.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"context"\n\t"fmt"\n\t"log/slog"\n\t"os"\n)\n\ntype SplitHandler struct {\n\tstdoutHandler slog.Handler\n\tfileHandler   slog.Handler\n}\n\nfunc NewSplitHandler(file *os.File) *SplitHandler {\n\treturn &SplitHandler{\n\t\tstdoutHandler: slog.NewJSONHandler(os.Stdout, &slog.HandlerOptions{Level: slog.LevelInfo}),\n\t\tfileHandler:   slog.NewJSONHandler(file, &slog.HandlerOptions{Level: slog.LevelError}),\n\t}\n}\n\nfunc (h *SplitHandler) Enabled(ctx context.Context, level slog.Level) bool {\n\treturn h.stdoutHandler.Enabled(ctx, level) || h.fileHandler.Enabled(ctx, level)\n}\n\nfunc (h *SplitHandler) Handle(ctx context.Context, r slog.Record) error {\n\tif h.stdoutHandler.Enabled(ctx, r.Level) {\n\t\t_ = h.stdoutHandler.Handle(ctx, r)\n\t}\n\tif r.Level >= slog.LevelError && h.fileHandler.Enabled(ctx, r.Level) {\n\t\t_ = h.fileHandler.Handle(ctx, r)\n\t}\n\treturn nil\n}\n\nfunc (h *SplitHandler) WithAttrs(attrs []slog.Attr) slog.Handler {\n\treturn &SplitHandler{\n\t\tstdoutHandler: h.stdoutHandler.WithAttrs(attrs),\n\t\tfileHandler:   h.fileHandler.WithAttrs(attrs),\n\t}\n}\n\nfunc (h *SplitHandler) WithGroup(name string) slog.Handler {\n\treturn &SplitHandler{\n\t\tstdoutHandler: h.stdoutHandler.WithGroup(name),\n\t\tfileHandler:   h.fileHandler.WithGroup(name),\n\t}\n}\n\nfunc main() {\n\terrFile, _ := os.Create("error.log")\n\tdefer func() {\n\t\terrFile.Close()\n\t\t_ = os.Remove("error.log")\n\t}()\n\n\tlogger := slog.New(NewSplitHandler(errFile))\n\n\tfmt.Println("--- Логи в Stdout ---")\n\tlogger.Info("Обычный запрос обработан успешно", "user", "alice")\n\tlogger.Error("Критический сбой базы данных", "error", "connection refused", "db", "postgres-primary")\n\n\terrData, _ := os.ReadFile("error.log")\n\tfmt.Println("\\n--- Содержимое файла error.log ---")\n\tfmt.Print(string(errData))\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# --- Логи в Stdout ---\n# {"time":"2026-09-02T18:40:00Z","level":"INFO","msg":"Обычный запрос обработан успешно","user":"alice"}\n# {"time":"2026-09-02T18:40:00Z","level":"ERROR","msg":"Критический сбой базы данных","error":"connection refused","db":"postgres-primary"}\n# \n# --- Содержимое файла error.log ---\n# {"time":"2026-09-02T18:40:00Z","level":"ERROR","msg":"Критический сбой базы данных","error":"connection refused","db":"postgres-primary"}'}], 'under_the_hood': 'Метод `Handle` клонирует `slog.Record` и передает его обоим обработчикам без взаимного влияния.', 'pitfalls': 'Обязательно реализуйте методы `WithAttrs` и `WithGroup`, создавая новые экземпляры `SplitHandler` для дочерних хендлеров.', 'bigtech_interview': '**Вопрос с собеседования:** «Почему в 12-Factor App рекомендуется писать все логи в stdout вместо разделения по файлам?»\n**Ответ:** Контейнеризированные приложения (Docker/K8s) отдают маршрутизацию логов инфраструктуре (Fluentbit, Promtail). Инфраструктурный агент сам разбирает поле `level` из stdout и отправляет `ERROR` в Sentry/Loki Alert, а `INFO` — в холодное хранилище.'}, {'num': 9, 'title': 'Отправка Error-логов во внешний Webhook/Sentry через кастомный slog.Handler', 'task': 'Реализуйте `slog.Handler`, который отправляет `Error`-логи в Sentry или аналогичную систему (через HTTP-запрос).', 'theory': 'Интеграция с системами мониторинга ошибок (Sentry, Bugsnag, Alertmanager) строится как специализированный `slog.Handler`, перехватывающий записи с `r.Level >= slog.LevelError` и отправляющий JSON-payload в асинхронный HTTP-канал.', 'step_by_step': '1. Создадим структуру `SentryHandler struct { next slog.Handler; webhookURL string }`.\n2. В методе `Handle(ctx, r)` проверим `if r.Level >= slog.LevelError`.\n3. Соберем атрибуты ошибки и отправим POST запрос.\n4. В `main` сымитируем HTTP-сервер Sentry через `httptest.Server` и протестируем отправку.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"bytes"\n\t"context"\n\t"encoding/json"\n\t"fmt"\n\t"log/slog"\n\t"net/http"\n\t"net/http/httptest"\n\t"os"\n)\n\ntype SentryAlertHandler struct {\n\tbaseHandler slog.Handler\n\tsentryURL   string\n}\n\nfunc (h *SentryAlertHandler) Enabled(ctx context.Context, level slog.Level) bool {\n\treturn h.baseHandler.Enabled(ctx, level)\n}\n\nfunc (h *SentryAlertHandler) Handle(ctx context.Context, r slog.Record) error {\n\t// 1. Всегда пишем в базовый stdout\n\t_ = h.baseHandler.Handle(ctx, r)\n\n\t// 2. Если ошибка — отправляем алерт во внешний Webhook\n\tif r.Level >= slog.LevelError {\n\t\tpayload := map[string]any{\n\t\t\t"timestamp": r.Time,\n\t\t\t"message":   r.Message,\n\t\t\t"level":     r.Level.String(),\n\t\t}\n\t\tr.Attrs(func(a slog.Attr) bool {\n\t\t\tpayload[a.Key] = a.Value.Any()\n\t\t\treturn true\n\t\t})\n\n\t\tbody, _ := json.Marshal(payload)\n\t\t// Асинхронная отправка (симуляция)\n\t\tgo func(data []byte) {\n\t\t\t_, _ = http.Post(h.sentryURL, "application/json", bytes.NewReader(data))\n\t\t}(body)\n\t}\n\treturn nil\n}\n\nfunc (h *SentryAlertHandler) WithAttrs(attrs []slog.Attr) slog.Handler {\n\treturn &SentryAlertHandler{baseHandler: h.baseHandler.WithAttrs(attrs), sentryURL: h.sentryURL}\n}\n\nfunc (h *SentryAlertHandler) WithGroup(name string) slog.Handler {\n\treturn &SentryAlertHandler{baseHandler: h.baseHandler.WithGroup(name), sentryURL: h.sentryURL}\n}\n\nfunc main() {\n\t// Симуляция сервера Sentry\n\tsentryMock := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {\n\t\tvar alert map[string]any\n\t\t_ = json.NewDecoder(r.Body).Decode(&alert)\n\t\tfmt.Printf("[SENTRY ALERT RECEIVED] Ошибка: %s | Детали: %v\\n", alert["message"], alert["component"])\n\t\tw.WriteHeader(http.StatusOK)\n\t}))\n\tdefer sentryMock.Close()\n\n\thandler := &SentryAlertHandler{\n\t\tbaseHandler: slog.NewJSONHandler(os.Stdout, nil),\n\t\tsentryURL:   sentryMock.URL,\n\t}\n\tlogger := slog.New(handler)\n\n\tlogger.Info("Штатный запуск модуля")\n\tlogger.Error("Падение пула соединений", slog.String("component", "RedisCluster"), slog.Int("retries", 3))\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# {"time":"2026-09-02T18:40:00Z","level":"INFO","msg":"Штатный запуск модуля"}\n# {"time":"2026-09-02T18:40:00Z","level":"ERROR","msg":"Падение пула соединений","component":"RedisCluster","retries":3}\n# [SENTRY ALERT RECEIVED] Ошибка: Падение пула соединений | Детали: RedisCluster'}], 'under_the_hood': 'Метод `r.Attrs(func(a slog.Attr) bool)` итерируется по всем атрибутам записи `slog.Record` без лишних аллокаций памяти.', 'pitfalls': 'Никогда не делайте синхронный сетевой `http.Post` внутри метода `Handle`, иначе сетевые задержки Sentry заблокируют выполнение всей программы. Используйте буферизованную очередь горутин.', 'bigtech_interview': '**Вопрос с собеседования:** «Как защитить сервис от падения, если Sentry недоступен или тормозит?»\n**Ответ:** Использовать неблокирующую отправку в кольцевой буфер (Ring Buffer) ограниченного размера (`chan AlertPayload` с `select default`). При переполнении буфера старые алерты сбрасываются (Drop Oldest), сохраняя стабильность основного сервиса.'}, {'num': 10, 'title': 'Контекстное логирование: проброс дочернего логгера через context.Context', 'task': '**[Контекстные логи]**: Создай middleware для HTTP-сервера, который генерирует `request_id` (UUID), создает дочерний логгер `logger.With("request_id", id)` и кладет его в `context.Context` (`slog.NewContext`). В обработчике достань логгер из контекста и запиши лог.', 'theory': 'Паттерн Context-Bound Logger позволяет передавать преднастроенный экземпляр логгера через стандартный `context.Context` по всей цепочке вызовов: `HTTP Handler -> Service -> Repository` без необходимости передавать `*slog.Logger` отдельным аргументом в каждую функцию.', 'step_by_step': '1. Создадим middleware с генерацией `request_id`.\n2. Создадим дочерний логгер: `subLogger := logger.With("request_id", reqID)`.\n3. Сохраним логгер в контекст через `ctx := context.WithValue(...)`.\n4. В сервисном слое извлечем логгер и сделаем запись.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"context"\n\t"fmt"\n\t"log/slog"\n\t"net/http"\n\t"net/http/httptest"\n\t"os"\n)\n\ntype ctxLoggerKey struct{}\n\nfunc InjectLoggerMiddleware(base *slog.Logger) func(http.Handler) http.Handler {\n\treturn func(next http.Handler) http.Handler {\n\t\treturn http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {\n\t\t\treqID := "uuid-8831-4421" // В проде: uuid.NewString()\n\t\t\treqLogger := base.With(slog.String("request_id", reqID), slog.String("uri", r.RequestURI))\n\n\t\t\tctx := context.WithValue(r.Context(), ctxLoggerKey{}, reqLogger)\n\t\t\tnext.ServeHTTP(w, r.WithContext(ctx))\n\t\t})\n\t}\n}\n\nfunc LoggerFromContext(ctx context.Context) *slog.Logger {\n\tif l, ok := ctx.Value(ctxLoggerKey{}).(*slog.Logger); ok {\n\t\treturn l\n\t}\n\treturn slog.Default()\n}\n\n// Доменный сервис получает только контекст\nfunc processPaymentService(ctx context.Context, amount int) {\n\tlog := LoggerFromContext(ctx)\n\tlog.Info("Обработка списания средств", "amount", amount, "gateway", "T-Bank")\n}\n\nfunc paymentHTTPHandler(w http.ResponseWriter, r *http.Request) {\n\tprocessPaymentService(r.Context(), 15000)\n\tw.WriteHeader(http.StatusOK)\n}\n\nfunc main() {\n\tjsonHandler := slog.NewJSONHandler(os.Stdout, nil)\n\tbaseLogger := slog.New(jsonHandler)\n\n\tmw := InjectLoggerMiddleware(baseLogger)\n\thandler := mw(http.HandlerFunc(paymentHTTPHandler))\n\n\treq := httptest.NewRequest(http.MethodPost, "/api/v1/payments", nil)\n\trec := httptest.NewRecorder()\n\n\tfmt.Println("--- Исполнение запроса с контекстным логгером ---")\n\thandler.ServeHTTP(rec, req)\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# --- Исполнение запроса с контекстным логгером ---\n# {"time":"2026-09-02T18:40:00Z","level":"INFO","msg":"Обработка списания средств","request_id":"uuid-8831-4421","uri":"/api/v1/payments","amount":15000,"gateway":"T-Bank"}'}], 'under_the_hood': '`context.WithValue` создает новый узел в дереве контекстов, хранящий указатель на иммутабельную структуру `*slog.Logger`.', 'pitfalls': 'Не мутируйте логгер в контексте — `logger.With` всегда возвращает новый независимый экземпляр.', 'bigtech_interview': '**Вопрос с собеседования:** «Каковы плюсы и минусы хранения логгера внутри context.Context?»\n**Ответ:** Плюсы: чистота сигнатур функций (не нужно протаскивать логгер 5-м параметром), автоматическое обогащение метаданными запроса. Минусы: скрытая зависимость (тип из контекста проверяется в runtime, а не в compile-time).'}, {'num': 11, 'title': 'Комплексный HTTP Middleware для структурированного аудита запросов', 'task': 'Напишите middleware, который логирует полный HTTP-запрос/ответ (method, path, status, latency, user_agent, ip) в структурированном JSON.', 'theory': 'Для логирования статус-кода ответа необходимо обернуть стандартный `http.ResponseWriter` в кастомную структуру `responseWriterInterceptor`, перехватывающую вызов `WriteHeader(statusCode)`.', 'step_by_step': '1. Создадим структуру `statusRecorder struct { http.ResponseWriter; statusCode int }`.\n2. В middleware зафиксируем `start := time.Now()`.\n3. В блоке `defer` рассчитаем `duration := time.Since(start)` и запишем структурированный лог через `logger.Info`.\n4. В `main` протестируем выполнение запроса.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"fmt"\n\t"log/slog"\n\t"net/http"\n\t"net/http/httptest"\n\t"os"\n\t"time"\n)\n\ntype statusRecorder struct {\n\thttp.ResponseWriter\n\tstatusCode int\n}\n\nfunc (r *statusRecorder) WriteHeader(code int) {\n\tr.statusCode = code\n\tr.ResponseWriter.WriteHeader(code)\n}\n\nfunc LoggingMiddleware(logger *slog.Logger) func(http.Handler) http.Handler {\n\treturn func(next http.Handler) http.Handler {\n\t\treturn http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {\n\t\t\tstart := time.Now()\n\t\t\trec := &statusRecorder{ResponseWriter: w, statusCode: http.StatusOK}\n\n\t\t\tdefer func() {\n\t\t\t\tlatency := time.Since(start)\n\t\t\t\tlogger.Info("HTTP Request Completed",\n\t\t\t\t\tslog.String("method", r.Method),\n\t\t\t\t\tslog.String("path", r.URL.Path),\n\t\t\t\t\tslog.Int("status", rec.statusCode),\n\t\t\t\t\tslog.Duration("latency", latency),\n\t\t\t\t\tslog.String("ip", r.RemoteAddr),\n\t\t\t\t\tslog.String("user_agent", r.UserAgent()),\n\t\t\t\t)\n\t\t\t}()\n\n\t\t\tnext.ServeHTTP(rec, r)\n\t\t})\n\t}\n}\n\nfunc apiHandler(w http.ResponseWriter, r *http.Request) {\n\tw.WriteHeader(http.StatusCreated)\n\t_, _ = w.Write([]byte(`{"id": 101}`))\n}\n\nfunc main() {\n\tlogger := slog.New(slog.NewJSONHandler(os.Stdout, nil))\n\tmw := LoggingMiddleware(logger)\n\n\thandler := mw(http.HandlerFunc(apiHandler))\n\n\treq := httptest.NewRequest(http.MethodPost, "/api/v1/orders", nil)\n\treq.Header.Set("User-Agent", "Go-Workout-Agent/1.0")\n\trec := httptest.NewRecorder()\n\n\tfmt.Println("--- Исполнение запроса через LoggingMiddleware ---")\n\thandler.ServeHTTP(rec, req)\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# --- Исполнение запроса через LoggingMiddleware ---\n# {"time":"2026-09-02T18:40:00Z","level":"INFO","msg":"HTTP Request Completed","method":"POST","path":"/api/v1/orders","status":201,"latency":15000,"ip":"192.0.2.1:1234","user_agent":"Go-Workout-Agent/1.0"}'}], 'under_the_hood': 'Обертка `statusRecorder` перехватывает первый вызов `WriteHeader`. Если хендлер пишет тело без явного вызова `WriteHeader`, по умолчанию используется статус `200 OK`.', 'pitfalls': 'Если хендлер паникует, `defer` в middleware все равно выполнится и залогирует время, затраченное до момента паники.', 'bigtech_interview': '**Вопрос с собеседования:** «Почему в HTTP middleware время запроса логируют строго в defer func()?»\n**Ответ:** 1) `defer` гарантирует вычисление `time.Since(start)` даже при панике внутри хендлера. 2) Только в конце обработки известен итоговый HTTP-статус код ответа.'}, {'num': 12, 'title': 'Кастомный slog.Handler для автоматического извлечения контекстных полей', 'task': '**Кастомный `slog.Handler` (Инжект контекста)**: Напиши обертку над `slog.JSONHandler`. Переопредели метод `Handle(ctx, record)`. Если в `ctx` лежит значение `RequestID` или `UserID`, твой хендлер должен автоматически добавлять эти поля в каждую строку лога.', 'theory': 'Переопределение метода `Handle(ctx, record)` в кастомном `slog.Handler` — самый чистый архитектурный паттерн в Go. Он позволяет использовать глобальный `slog.InfoContext(ctx, ...)` без передачи дочерних логгеров, автоматически обогащая каждую запись полями из `ctx`.', 'step_by_step': '1. Создадим структуру `ContextAwareHandler struct { slog.Handler }`.\n2. Переопределим `Handle(ctx context.Context, r slog.Record) error`.\n3. Проверим наличие значений `ctx.Value("request_id")` и `ctx.Value("user_id")` и добавим их через `r.AddAttrs(...)`.\n4. В `main` вызовем `slog.InfoContext(ctx, "сообщение")` и проверим добавление полей.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"context"\n\t"fmt"\n\t"log/slog"\n\t"os"\n)\n\ntype ctxKey string\n\nconst (\n\tCtxRequestID ctxKey = "request_id"\n\tCtxUserID    ctxKey = "user_id"\n)\n\ntype ContextInjectHandler struct {\n\tslog.Handler\n}\n\nfunc (h *ContextInjectHandler) Handle(ctx context.Context, r slog.Record) error {\n\t// Извлекаем контекстные поля, если они есть\n\tif reqID, ok := ctx.Value(CtxRequestID).(string); ok && reqID != "" {\n\t\tr.AddAttrs(slog.String("request_id", reqID))\n\t}\n\tif userID, ok := ctx.Value(CtxUserID).(int); ok && userID != 0 {\n\t\tr.AddAttrs(slog.Int("user_id", userID))\n\t}\n\n\treturn h.Handler.Handle(ctx, r)\n}\n\nfunc main() {\n\tbaseJSON := slog.NewJSONHandler(os.Stdout, nil)\n\tinjectHandler := &ContextInjectHandler{Handler: baseJSON}\n\tlogger := slog.New(injectHandler)\n\tslog.SetDefault(logger)\n\n\t// Контекст запроса с метаданными\n\tctx := context.Background()\n\tctx = context.WithValue(ctx, CtxRequestID, "req-99001-xyz")\n\tctx = context.WithValue(ctx, CtxUserID, 42)\n\n\tfmt.Println("--- Логирование через slog.InfoContext ---")\n\tslog.InfoContext(ctx, "Пользователь открыл страницу каталога", "category", "electronics")\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# --- Логирование через slog.InfoContext ---\n# {"time":"2026-09-02T18:40:00Z","level":"INFO","msg":"Пользователь открыл страницу каталога","category":"electronics","request_id":"req-99001-xyz","user_id":42}'}], 'under_the_hood': '`r.AddAttrs` мутирует копию `slog.Record`, переданную по значению в метод `Handle`, добавляя атрибуты в конец списка без изменения оригинальной записи.', 'pitfalls': 'Используйте `slog.InfoContext(ctx, ...)` вместо `slog.Info(...)`, иначе переданный контекст будет `nil` или `context.Background()`.', 'bigtech_interview': '**Вопрос с собеседования:** «В чем преимущество Context Handler перед logger.With()?»\n**Ответ:** Разработчикам не нужно протаскивать объект логгера сквозь все сигнатуры функций — достаточно передавать стандартный `context.Context` и вызывать `slog.InfoContext(ctx)`. Хендлер автоматически извлечет нужные идентификаторы.'}, {'num': 13, 'title': 'Zero-Allocation логирование в горячих путях через slog.LogAttrs', 'task': 'Используйте `slog.LogAttrs` для zero-allocation логирования в горячих путях (high-performance logging без аллокаций).', 'theory': 'Обычный вызов `logger.Info(msg, "key", val)` упаковывает аргументы в срез `...any`, что создает аллокацию памяти в куче для каждого аргумента (boxing interface{}). Метод `logger.LogAttrs(ctx, level, msg, attrs...)` принимает строго типизированные `slog.Attr`, обеспечивая **0 аллокаций памяти**.', 'step_by_step': '1. Создадим JSON-логгер.\n2. Подготовим типизированные атрибуты `slog.Int64`, `slog.String`, `slog.Float64`.\n3. Вызовем `logger.LogAttrs(ctx, slog.LevelInfo, "HotPath Event", ...)`.\n4. В `main` убедимся в корректном выводе.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"context"\n\t"log/slog"\n\t"os"\n)\n\nfunc main() {\n\tlogger := slog.New(slog.NewJSONHandler(os.Stdout, nil))\n\tctx := context.Background()\n\n\t// HighLoad Zero-Allocation вызов без упаковки в ...any:\n\tlogger.LogAttrs(ctx, slog.LevelInfo, "Order Processed Fast",\n\t\tslog.Int64("order_id", 88910293),\n\t\tslog.String("currency", "RUB"),\n\t\tslog.Float64("price", 1990.50),\n\t\tslog.Bool("is_vip", true),\n\t)\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# {"time":"2026-09-02T18:40:00Z","level":"INFO","msg":"Order Processed Fast","order_id":88910293,"currency":"RUB","price":1990.5,"is_vip":true}'}], 'under_the_hood': '`slog.Attr` — это структура из двух полей (`string` и `slog.Value`), где базовые числа хранятся в 64-битном поле без выделения памяти в куче.', 'pitfalls': 'Вызов `slog.Any("key", val)` для кастомных структур все равно аллоцирует память. Для структур реализуйте `slog.LogValuer`.', 'bigtech_interview': '**Вопрос с собеседования:** «Почему logger.Info("msg", "key", 10) аллоцирует память, а logger.LogAttrs(ctx, LevelInfo, "msg", slog.Int("key", 10)) — нет?»\n**Ответ:** Нетипизированный `logger.Info` принимает `...any`. Приведение числа `10` к `any` (interface{}) заставляет рантайм Go выделить память в куче (Escape to heap / boxing). `slog.Int` возвращает структуру `slog.Attr` со значением на стеке без упаковки в интерфейс.'}, {'num': 14, 'title': 'Создание вложенного поддерева логов через logger.WithGroup', 'task': '**[Группировка]**: Используй `logger.WithGroup("user")`. Все последующие атрибуты (например, "id", "name") должны оказаться внутри JSON-объекта `"user": {...}`.', 'theory': 'Метод `logger.WithGroup(name)` создает дочерний логгер, у которого все последующие поля автоматически группируются во вложенный JSON-объект `{"user": {"id": 42, "name": "Alice"}}`.', 'step_by_step': '1. Создадим базовый JSON-логгер.\n2. Создадим дочерний логгер `userLogger := baseLogger.WithGroup("user")`.\n3. Добавим атрибуты через `userLogger.With(slog.Int("id", 42))`.\n4. Вызовем `userLogger.Info("пользователь авторизован", "role", "admin")`.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"log/slog"\n\t"os"\n)\n\nfunc main() {\n\tbaseLogger := slog.New(slog.NewJSONHandler(os.Stdout, nil))\n\n\t// Дочерний логгер для модуля управления пользователями\n\tuserLogger := baseLogger.WithGroup("user")\n\n\tuserLogger.Info("Успешная авторизация в системе",\n\t\tslog.Int("id", 42),\n\t\tslog.String("name", "Alice"),\n\t\tslog.String("role", "admin"),\n\t)\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# {"time":"2026-09-02T18:40:00Z","level":"INFO","msg":"Успешная авторизация в системе","user":{"id":42,"name":"Alice","role":"admin"}}'}], 'under_the_hood': '`WithGroup` запоминает путь группы в цепочке `slog.Handler`. При сериализации атрибутов открывается новый уровень вложенности JSON.', 'pitfalls': 'Поля, добавленные до `WithGroup`, остаются на верхнем уровне JSON, а поля после `WithGroup` попадают внутрь вложенного объекта.', 'bigtech_interview': '**Вопрос с собеседования:** «Зачем нужна группировка логов в микросервисах?»\n**Ответ:** Чтобы избежать коллизий имен полей (Namespace Isolation). Например, поле `id` может относиться к `user.id`, `order.id` или `transaction.id`.'}, {'num': 15, 'title': 'Сквозной аудит HTTP-запросов с генерацией X-Request-ID', 'task': 'Реализуйте HTTP-middleware, который генерирует (или пробрасывает) `X-Request-ID`, кладёт его в контекст и логирует каждый запрос: метод, URL, статус, длительность — структурированно.', 'theory': 'Заголовок `X-Request-ID` обеспечивает сквозную трассировку пользовательского клика через весь микросервисный граф: Nginx -> API Gateway -> Auth -> Billing -> DB.', 'step_by_step': '1. Если заголовок `X-Request-ID` пришел от клиента — переиспользуем его. Если нет — генерируем новый.\n2. Сохраняем `request_id` в контекст и выставляем в `w.Header()`.\n3. Логируем структурированную запись в конце обработки.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"context"\n\t"fmt"\n\t"log/slog"\n\t"net/http"\n\t"net/http/httptest"\n\t"os"\n\t"time"\n)\n\ntype reqKey struct{}\n\ntype loggingResponseWriter struct {\n\thttp.ResponseWriter\n\tstatus int\n}\n\nfunc (lrw *loggingResponseWriter) WriteHeader(code int) {\n\tlrw.status = code\n\tlrw.ResponseWriter.WriteHeader(code)\n}\n\nfunc TraceAuditMiddleware(logger *slog.Logger) func(http.Handler) http.Handler {\n\treturn func(next http.Handler) http.Handler {\n\t\treturn http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {\n\t\t\treqID := r.Header.Get("X-Request-ID")\n\t\t\tif reqID == "" {\n\t\t\t\treqID = "gen-trace-9918274" // В проде: uuid.New().String()\n\t\t\t}\n\n\t\t\tw.Header().Set("X-Request-ID", reqID)\n\t\t\tctx := context.WithValue(r.Context(), reqKey{}, reqID)\n\n\t\t\tstart := time.Now()\n\t\t\tlrw := &loggingResponseWriter{ResponseWriter: w, status: http.StatusOK}\n\n\t\t\tdefer func() {\n\t\t\t\tlogger.Info("Audit HTTP Access Log",\n\t\t\t\t\tslog.String("request_id", reqID),\n\t\t\t\t\tslog.String("method", r.Method),\n\t\t\t\t\tslog.String("url", r.URL.String()),\n\t\t\t\t\tslog.Int("status", lrw.status),\n\t\t\t\t\tslog.Duration("latency", time.Since(start)),\n\t\t\t\t)\n\t\t\t}()\n\n\t\t\tnext.ServeHTTP(lrw, r.WithContext(ctx))\n\t\t})\n\t}\n}\n\nfunc main() {\n\tlogger := slog.New(slog.NewJSONHandler(os.Stdout, nil))\n\tmw := TraceAuditMiddleware(logger)\n\n\ttestHandler := mw(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {\n\t\tw.WriteHeader(http.StatusOK)\n\t}))\n\n\treq := httptest.NewRequest(http.MethodGet, "/catalog/products?page=1", nil)\n\trec := httptest.NewRecorder()\n\n\tfmt.Println("--- Выполнение запроса с аудитом ---")\n\ttestHandler.ServeHTTP(rec, req)\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# --- Выполнение запроса с аудитом ---\n# {"time":"2026-09-02T18:40:00Z","level":"INFO","msg":"Audit HTTP Access Log","request_id":"gen-trace-9918274","method":"GET","url":"/catalog/products?page=1","status":200,"latency":12000}'}], 'under_the_hood': 'Заголовок `X-Request-ID` передается во всех исходящих HTTP/gRPC запросах к дочерним сервисам через метаданные контекста.', 'pitfalls': 'Не забывайте передавать `X-Request-ID` в исходящем заголовке ответа `w.Header().Set("X-Request-ID", reqID)` для отладки фронтендом.', 'bigtech_interview': '**Вопрос с собеседования:** «Зачем клиенту возвращать заголовок X-Request-ID в ответе на HTTP 500?»\n**Ответ:** Пользователь или служба поддержки при возникновении ошибки могут скопировать `Request-ID` из ответа браузера и передать инженерам, которые мгновенно найдут точный лог и трейс сбоя в Kibana/Loki.'}, {'num': 16, 'title': 'Сэмплирование логов (Log Sampling): 100% ошибок и 10% информационных логов', 'task': 'Реализуйте log sampling: логируйте 100% ошибок, но только каждый 10-й Info-лог для снижения объема в высоконагруженных сервисах.', 'theory': 'Log Sampling (интервальное или вероятностное сэмплирование) сокращает затраты на хранение терабайтов логов в 10–100 раз при сохранении 100% видимости всех критических ошибок и исключений.', 'step_by_step': '1. Создадим структуру `SamplingHandler struct { next slog.Handler; counter atomic.Uint64; rate uint64 }`.\n2. В методе `Enabled` пропускаем 100% записей с уровнем `LevelError` и выше.\n3. Для `LevelInfo` пропускаем только записи, где `counter.Add(1) % rate == 0`.\n4. В `main` сгенерируем 20 информационных логов и убедимся, что напечатано ровно 2.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"context"\n\t"fmt"\n\t"log/slog"\n\t"os"\n\t"sync/atomic"\n)\n\ntype SamplingHandler struct {\n\tnext    slog.Handler\n\tcounter atomic.Uint64\n\trate    uint64 // Пропускать 1 из rate (например, 10)\n}\n\nfunc (h *SamplingHandler) Enabled(ctx context.Context, level slog.Level) bool {\n\treturn h.next.Enabled(ctx, level)\n}\n\nfunc (h *SamplingHandler) Handle(ctx context.Context, r slog.Record) error {\n\t// Ошибки логируются ВСЕГДА (100% сэмплинг)\n\tif r.Level >= slog.LevelError {\n\t\treturn h.next.Handle(ctx, r)\n\t}\n\n\t// Информационные логи сэмплируются (1 из rate)\n\tif h.counter.Add(1)%h.rate == 0 {\n\t\treturn h.next.Handle(ctx, r)\n\t}\n\n\treturn nil // Пропускаем лог\n}\n\nfunc (h *SamplingHandler) WithAttrs(attrs []slog.Attr) slog.Handler {\n\treturn &SamplingHandler{next: h.next.WithAttrs(attrs), rate: h.rate}\n}\n\nfunc (h *SamplingHandler) WithGroup(name string) slog.Handler {\n\treturn &SamplingHandler{next: h.next.WithGroup(name), rate: h.rate}\n}\n\nfunc main() {\n\tbaseJSON := slog.NewJSONHandler(os.Stdout, nil)\n\tsampler := &SamplingHandler{next: baseJSON, rate: 10}\n\tlogger := slog.New(sampler)\n\n\tfmt.Println("--- Генерация 20 Info логов (сэмплинг 1/10) и 1 Error лога ---")\n\tfor i := 1; i <= 20; i++ {\n\t\tlogger.Info("Рутинный запрос проверки статуса", "iteration", i)\n\t}\n\n\tlogger.Error("Критический отказ платежного шлюза", "error", "timeout")\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# --- Генерация 20 Info логов (сэмплинг 1/10) и 1 Error лога ---\n# {"time":"2026-09-02T18:40:00Z","level":"INFO","msg":"Рутинный запрос проверки статуса","iteration":10}\n# {"time":"2026-09-02T18:40:00Z","level":"INFO","msg":"Рутинный запрос проверки статуса","iteration":20}\n# {"time":"2026-09-02T18:40:00Z","level":"ERROR","msg":"Критический отказ платежного шлюза","error":"timeout"}'}], 'under_the_hood': '`atomic.Uint64.Add` выполняется как lock-free процессорная инструкция `LOCK XADD`.', 'pitfalls': 'Не применяйте сэмплирование к финансовым аудиторским логам или событиям авторизации безопасности.', 'bigtech_interview': '**Вопрос с собеседования:** «Как устроен сэмплинг в Uber Zap (zapcore.NewSamplerCore)?»\n**Ответ:** Zap логирует первые $N$ записей с одинаковым сообщением в секунду (Initial), а затем пропускает только каждую $M$-ю запись (Thereafter) с автосбросом счетчика каждую секунду.'}, {'num': 17, 'title': 'Безопасное логирование объектов пользователя без утечки паролей', 'task': '**[Каверзный кейс]**: Логирование секретов. Напиши структуру `User` с методом `LogValue() slog.Value`, который возвращает только `id` и `name`, скрывая поле `password`. Передай структуру в `slog.Info`.', 'theory': 'Реализация метода `LogValue()` с белым списком разрешенных полей гарантирует, что даже при добавлении новых секретных полей в структуру `User` они никогда случайно не попадут в логи.', 'step_by_step': '1. Объявим структуру `User struct { ID int; Name string; PasswordHash string; SecretSalt string }`.\n2. Реализуем `(u User) LogValue() slog.Value`.\n3. Внутри метода вернем только безопасные поля `ID` и `Name`.\n4. В `main` вызовем `logger.Info`.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"log/slog"\n\t"os"\n)\n\ntype UserAccount struct {\n\tID           int\n\tName         string\n\tPasswordHash string\n\tSecretSalt   string\n}\n\n// LogValue гарантирует белый список логируемых полей\nfunc (u UserAccount) LogValue() slog.Value {\n\treturn slog.GroupValue(\n\t\tslog.Int("id", u.ID),\n\t\tslog.String("name", u.Name),\n\t)\n}\n\nfunc main() {\n\tlogger := slog.New(slog.NewJSONHandler(os.Stdout, nil))\n\n\taccount := UserAccount{\n\t\tID:           501,\n\t\tName:         "Dmitry",\n\t\tPasswordHash: "$2a$12$e8Y9X7U8J8K9...",\n\t\tSecretSalt:   "0xDEADBEEF99",\n\t}\n\n\tlogger.Info("Сессия пользователя создана", "account", account)\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# {"time":"2026-09-02T18:40:00Z","level":"INFO","msg":"Сессия пользователя создана","account":{"id":501,"name":"Dmitry"}}'}], 'under_the_hood': '`slog.GroupValue` создает объект `slog.Value` с типом `KindGroup`.', 'pitfalls': 'Если забыть объявить `LogValue`, `slog` через рефлексию выведет все экспортируемые поля структуры вместе с хэшами паролей!', 'bigtech_interview': '**Вопрос с собеседования:** «Почему маскирование через LogValue надежнее ручного удаления полей перед каждым вызовом лога?»\n**Ответ:** Ручное маскирование подвержено человеческому фактору: разработчик может забыть замаскировать поле в одном из 50 мест кодовой базы. `LogValue` централизованно защищает структуру во всех вызовах логирования.'}, {'num': 18, 'title': 'Логирование Stack Trace в виде структурированного JSON-массива строк', 'task': '**Логирование Stack Trace**: В Go ошибки не содержат стек вызовов по умолчанию. Используй библиотеку (например, `github.com/pkg/errors` или форки). Напиши функцию, генерирующую ошибку с трейсом. При логировании ошибки разбери трейс и запиши его в лог как массив строк (чтобы в ELK/Kibana это не превратилось в нечитаемую простыню с `\\n`).', 'theory': 'Запись стека вызовов в виде структурированного JSON-массива `["main.go:42", "service.go:15"]` вместо одной многострочной строки с `\\n` позволяет Kibana/Loki корректно парсить и отображать трейс без разрывов строк в интерфейсе.', 'step_by_step': '1. Напишем функцию захвата стека через `runtime.Callers` и `runtime.CallersFrames`.\n2. Сформируем срез строк `[]string` с путями к файлам и номерами строк.\n3. Запишем `slog.Error` с атрибутом `slog.Any("stack_trace", frames)`.\n4. В `main` убедимся в красивом JSON-массиве трейса.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"fmt"\n\t"log/slog"\n\t"os"\n\t"runtime"\n)\n\nfunc captureStackTrace() []string {\n\tpc := make([]uintptr, 10)\n\tn := runtime.Callers(2, pc) // Пропускаем captureStackTrace и runtime.Callers\n\tframes := runtime.CallersFrames(pc[:n])\n\n\tvar trace []string\n\tfor {\n\t\tframe, more := frames.Next()\n\t\ttrace = append(trace, fmt.Sprintf("%s:%d (%s)", frame.File, frame.Line, frame.Function))\n\t\tif !more {\n\t\t\tbreak\n\t\t}\n\t}\n\treturn trace\n}\n\nfunc executeFaultyOperation() {\n\t// Симуляция ошибки с захватом стека\n\ttrace := captureStackTrace()\n\tslog.Error("Непредвиденный сбой транзакции",\n\t\tslog.String("error", "database deadlock detected"),\n\t\tslog.Any("stack_trace", trace),\n\t)\n}\n\nfunc main() {\n\tlogger := slog.New(slog.NewJSONHandler(os.Stdout, nil))\n\tslog.SetDefault(logger)\n\n\texecuteFaultyOperation()\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# {"time":"2026-09-02T18:40:00Z","level":"ERROR","msg":"Непредвиденный сбой транзакции","error":"database deadlock detected","stack_trace":["/home/ut/work/go-workout/main.go:27 (main.executeFaultyOperation)","/home/ut/work/go-workout/main.go:37 (main.main)"]}'}], 'under_the_hood': '`runtime.Callers` читает адреса возврата непосредственно из фреймов стека текущей горутины.', 'pitfalls': 'Сбор стектрейса требует поиска символов в таблице символов DWARF рантайма. Собирайте стек только для уровня `LevelError`, а не для каждого `Info` лога.', 'bigtech_interview': '**Вопрос с собеседования:** «Каковы накладные расходы runtime.Callers на производительность?»\n**Ответ:** Захват стека глубиной 10 фреймов занимает около 1-3 микросекунд. В высоконагруженных циклах (100k RPS) это может вызвать деградацию CPU, поэтому стектрейс снимают исключительно при аварийных ошибках.'}, {'num': 19, 'title': 'Интеграция slog с OpenTelemetry: Trace ID и Span ID корреляция', 'task': "Напишите интеграцию `slog` с OpenTelemetry: каждый лог автоматически содержит `trace_id` и `span_id` текущего span'а для корреляции логов с трейсами.", 'theory': 'Log-to-Trace Correlation (корреляция логов и распределенных трейсов) связывает каждую строчку лога с графиком трассировки запроса в Jaeger/Grafana Tempo через поля `trace_id` и `span_id`.', 'step_by_step': '1. Создадим структуру контекста с идентификаторами `trace_id` (128-бит hex) и `span_id` (64-бит hex).\n2. Напишем `OtelTracingHandler`, извлекающий `TraceID` из `ctx` и добавляющий их в запись лога.\n3. В `main` вызовем `logger.InfoContext(ctx, "обработка запроса")`.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"context"\n\t"fmt"\n\t"log/slog"\n\t"os"\n)\n\ntype traceContextKey struct{}\n\ntype TraceSpanInfo struct {\n\tTraceID string\n\tSpanID  string\n}\n\ntype OtelTracingHandler struct {\n\tslog.Handler\n}\n\nfunc (h *OtelTracingHandler) Handle(ctx context.Context, r slog.Record) error {\n\tif span, ok := ctx.Value(traceContextKey{}).(TraceSpanInfo); ok {\n\t\tr.AddAttrs(\n\t\t\tslog.String("trace_id", span.TraceID),\n\t\t\tslog.String("span_id", span.SpanID),\n\t\t)\n\t}\n\treturn h.Handler.Handle(ctx, r)\n}\n\nfunc main() {\n\tbaseJSON := slog.NewJSONHandler(os.Stdout, nil)\n\totelHandler := &OtelTracingHandler{Handler: baseJSON}\n\tlogger := slog.New(otelHandler)\n\n\t// Имитация контекста со спаном OpenTelemetry\n\tctx := context.WithValue(context.Background(), traceContextKey{}, TraceSpanInfo{\n\t\tTraceID: "4bf92f3577b34da6a3ce929d0e0e4736",\n\t\tSpanID:  "00f067aa0ba902b7",\n\t})\n\n\tfmt.Println("--- Логирование с Trace Correlation ---")\n\tlogger.InfoContext(ctx, "gRPC вызов к сервису авторизации",\n\t\tslog.String("peer.service", "auth-v2"),\n\t\tslog.Int("rpc.status_code", 0),\n\t)\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# --- Логирование с Trace Correlation ---\n# {"time":"2026-09-02T18:40:00Z","level":"INFO","msg":"gRPC вызов к сервису авторизации","peer.service":"auth-v2","rpc.status_code":0,"trace_id":"4bf92f3577b34da6a3ce929d0e0e4736","span_id":"00f067aa0ba902b7"}'}], 'under_the_hood': 'В реальном OpenTelemetry Go SDK вызов `trace.SpanFromContext(ctx).SpanContext()` возвращает `trace.TraceID` и `trace.SpanID`.', 'pitfalls': 'Форматируйте `TraceID` строго как 32-символьную hex-строку, а `SpanID` как 16-символьную hex-строку в нижнем регистре по спецификации W3C Trace Context.', 'bigtech_interview': '**Вопрос с собеседования:** «Как инженер по щелчку мыши в Grafana Loki переходит в трейс Jaeger?»\n**Ответ:** Grafana парсит поле `trace_id` из JSON-лога и формирует прямую ссылку (Derived Field) на дэшборд Tempo/Jaeger `https://tempo/trace/${__value.raw}`, мгновенно открывая таймлайн всех спанов запроса.'}, {'num': 20, 'title': 'Управление уровнем логирования через системный сигнал SIGUSR1', 'task': 'Поддержите динамическое изменение уровня логирования без перезапуска (через эндпоинт или сигнал `SIGUSR1`).', 'theory': 'Сигналы POSIX (`SIGUSR1`, `SIGHUP`) позволяют менять внутреннее состояние демона без сетевого трафика. Канал `chan os.Signal` перехватывает `SIGUSR1` и переключает `slog.LevelVar` между `INFO` и `DEBUG`.', 'step_by_step': '1. Создадим `levelVar := new(slog.LevelVar)`.\n2. Создадим канал `sigCh := make(chan os.Signal, 1)`.\n3. Подпишемся на `signal.Notify(sigCh, syscall.SIGUSR1)`.\n4. В фоновой горутине переключим уровень при получении сигнала.\n5. В `main` сымитируем переключение уровня.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"fmt"\n\t"log/slog"\n\t"os"\n\t"os/signal"\n\t"syscall"\n)\n\nfunc setupSignalLogLevel(levelVar *slog.LevelVar) {\n\tsigCh := make(chan os.Signal, 1)\n\tsignal.Notify(sigCh, syscall.SIGUSR1)\n\n\tgo func() {\n\t\tfor range sigCh {\n\t\t\tif levelVar.Level() == slog.LevelInfo {\n\t\t\t\tlevelVar.Set(slog.LevelDebug)\n\t\t\t\tslog.Info("[SIGNAL SIGUSR1] Уровень логирования переключен на DEBUG")\n\t\t\t} else {\n\t\t\t\tlevelVar.Set(slog.LevelInfo)\n\t\t\t\tslog.Info("[SIGNAL SIGUSR1] Уровень логирования переключен на INFO")\n\t\t\t}\n\t\t}\n\t}()\n}\n\nfunc main() {\n\tlevelVar := new(slog.LevelVar)\n\tlevelVar.Set(slog.LevelInfo)\n\n\tlogger := slog.New(slog.NewTextHandler(os.Stdout, &slog.HandlerOptions{Level: levelVar}))\n\tslog.SetDefault(logger)\n\n\tsetupSignalLogLevel(levelVar)\n\n\tfmt.Println("=== Режим 1: По умолчанию (INFO) ===")\n\tslog.Debug("Скрытое отладочное сообщение")\n\tslog.Info("Сервер работает в штатном режиме")\n\n\t// Имитация получения сигнала SIGUSR1:\n\tfmt.Println("\\n=== Имитация отправки сигнала SIGUSR1 ===")\n\tlevelVar.Set(slog.LevelDebug)\n\n\tslog.Debug("Отладочный лог: соединение с БД активно (pool_size=20)")\n\tslog.Info("Запрос выполнен успешно")\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# === Режим 1: По умолчанию (INFO) ===\n# time=2026-09-02T18:40:00.000Z level=INFO msg="Сервер работает в штатном режиме"\n# \n# === Имитация отправки сигнала SIGUSR1 ===\n# time=2026-09-02T18:40:00.000Z level=DEBUG msg="Отладочный лог: соединение с БД активно (pool_size=20)"\n# time=2026-09-02T18:40:00.000Z level=INFO msg="Запрос выполнен успешно" '}], 'under_the_hood': 'Сигнал ОС обрабатывается в отдельном потоке рантайма Go (сигнальный поток M), который отправляет событие в канал Go без блокировки рабочих горутин.', 'pitfalls': 'Канал сигналов `make(chan os.Signal, 1)` обязан быть буферизованным, иначе сигнал ядра может быть утерян.', 'bigtech_interview': '**Вопрос с собеседования:** «Как отправить SIGUSR1 процессу в Kubernetes pod?»\n**Ответ:** Выполнить команду `kubectl exec pod-name -- kill -SIGUSR1 1` (где 1 — PID основного процесса контейнера).'}, {'num': 21, 'title': 'Кастомный LogValuer для вывода time.Duration в миллисекундах', 'task': 'Создай кастомный `LogValuer` для `time.Duration`, чтобы в логах длительность выводилась в миллисекундах, а не в наносекундах.', 'theory': 'По умолчанию `slog.JSONHandler` сериализует `time.Duration` в наносекундах (целое число), что затрудняет чтение человеком. Обертка `type Millis time.Duration` с методом `LogValue()` форматирует время в виде дробных миллисекунд `15.42ms` или числа `15.42`.', 'step_by_step': '1. Объявим тип `type LatencyMs time.Duration`.\n2. Реализуем метод `(l LatencyMs) LogValue() slog.Value`.\n3. Внутри метода вернем `slog.Float64Value(float64(time.Duration(l).Microseconds()) / 1000.0)`.\n4. В `main` проверим красивый вывод задержки в миллисекундах.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"log/slog"\n\t"os"\n\t"time"\n)\n\ntype Millis time.Duration\n\nfunc (m Millis) LogValue() slog.Value {\n\tms := float64(time.Duration(m).Microseconds()) / 1000.0\n\treturn slog.Float64Value(ms)\n}\n\nfunc main() {\n\tlogger := slog.New(slog.NewJSONHandler(os.Stdout, nil))\n\n\tduration := 15420 * time.Microsecond // 15.42 мс\n\n\tlogger.Info("Вызов внешнего API завершен",\n\t\tslog.String("endpoint", "https://api.payment.corp/charge"),\n\t\tslog.Any("latency_ms", Millis(duration)),\n\t)\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# {"time":"2026-09-02T18:40:00Z","level":"INFO","msg":"Вызов внешнего API завершен","endpoint":"https://api.payment.corp/charge","latency_ms":15.42}'}], 'under_the_hood': '`slog.Float64Value` создает структуру значения с типом `KindFloat64` без упаковки в `interface{}`.', 'pitfalls': 'Использование `time.Duration.Milliseconds()` отбрасывает дробную часть (15 вместо 15.42). Для точности делите микросекунды на 1000.0.', 'bigtech_interview': '**Вопрос с собеседования:** «Почему Prometheus и OpenTelemetry рекомендуют хранить задержки в секундах или миллисекундах float64?»\n**Ответ:** Чтобы использовать стандартные единицы измерения СИ для агрегации перцентилей (p50, p95, p99) и вычисления средних значений без путаницы с множителями $10^9$.'}, {'num': 22, 'title': 'Асинхронный логгер с буферизованным каналом и фоновым воркером', 'task': '**[Асинхронное логирование]**: Если логов очень много, запись в stdout может тормозить горутины. Реализуй буферизированный канал, в который пишутся логи, а фоновая горутина читает их и пишет в `os.Stdout` (или файл).', 'theory': 'Синхронная запись в `os.Stdout` или на диск блокирует рабочие горутины при всплесках нагрузки. Асинхронный обработчик использует буферизованный канал (Ring Buffer) и фонового воркера, защищая бизнес-логику от задержек I/O.', 'step_by_step': '1. Создадим структуру `AsyncHandler struct { queue chan slog.Record; next slog.Handler }`.\n2. В конструкторе запустим горутину-воркер `for r := range queue`.\n3. В методе `Handle` неблокирующе отправим запись в канал (`select default`).\n4. В методе `Close()` закроем канал и дождемся сброса очереди.\n5. В `main` протестируем асинхронный логгер.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"context"\n\t"fmt"\n\t"log/slog"\n\t"os"\n\t"sync"\n\t"time"\n)\n\ntype AsyncHandler struct {\n\tnext    slog.Handler\n\tqueue   chan slog.Record\n\twg      sync.WaitGroup\n\tdropped int64\n}\n\nfunc NewAsyncHandler(next slog.Handler, bufferSize int) *AsyncHandler {\n\th := &AsyncHandler{\n\t\tnext:  next,\n\t\tqueue: make(chan slog.Record, bufferSize),\n\t}\n\n\th.wg.Add(1)\n\tgo func() {\n\t\tdefer h.wg.Done()\n\t\tfor r := range h.queue {\n\t\t\t_ = h.next.Handle(context.Background(), r)\n\t\t}\n\t}()\n\n\treturn h\n}\n\nfunc (h *AsyncHandler) Enabled(ctx context.Context, level slog.Level) bool {\n\treturn h.next.Enabled(ctx, level)\n}\n\nfunc (h *AsyncHandler) Handle(ctx context.Context, r slog.Record) error {\n\t// Клонируем запись для безопасной передачи между горутинами\n\trecCopy := r.Clone()\n\n\tselect {\n\tcase h.queue <- recCopy:\n\t\treturn nil\n\tdefault:\n\t\t// Буфер переполнен (Drop to protect throughput)\n\t\th.dropped++\n\t\treturn nil\n\t}\n}\n\nfunc (h *AsyncHandler) WithAttrs(attrs []slog.Attr) slog.Handler {\n\treturn &AsyncHandler{next: h.next.WithAttrs(attrs), queue: h.queue}\n}\n\nfunc (h *AsyncHandler) WithGroup(name string) slog.Handler {\n\treturn &AsyncHandler{next: h.next.WithGroup(name), queue: h.queue}\n}\n\nfunc (h *AsyncHandler) Close() {\n\tclose(h.queue)\n\th.wg.Wait()\n}\n\nfunc main() {\n\tbaseJSON := slog.NewJSONHandler(os.Stdout, nil)\n\tasyncH := NewAsyncHandler(baseJSON, 100)\n\tlogger := slog.New(asyncH)\n\n\tfor i := 1; i <= 3; i++ {\n\t\tlogger.Info("Асинхронная обработка транзакции", "tx_id", i)\n\t}\n\n\t// Гарантированный сброс очереди при завершении сервиса\n\tasyncH.Close()\n\tfmt.Println("Все асинхронные логи успешно сброшены в stdout")\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# {"time":"2026-09-02T18:40:00Z","level":"INFO","msg":"Асинхронная обработка транзакции","tx_id":1}\n# {"time":"2026-09-02T18:40:00Z","level":"INFO","msg":"Асинхронная обработка транзакции","tx_id":2}\n# {"time":"2026-09-02T18:40:00Z","level":"INFO","msg":"Асинхронная обработка транзакции","tx_id":3}\n# Все асинхронные логи успешно сброшены в stdout'}], 'under_the_hood': '`r.Clone()` копирует атрибуты записи, так как `slog.Record` может переиспользовать внутренний срез в вызывающей горутине.', 'pitfalls': 'Обязательно вызывайте `asyncH.Close()` при `Graceful Shutdown`, иначе последние записи из очереди будут потеряны при завершении процесса.', 'bigtech_interview': '**Вопрос с собеседования:** «Что делать, если очередь асинхронного логгера переполнилась при миллионе RPS?»\n**Ответ:** 1) Сбрасывать информационные логи (`select default: drop`). 2) Ошибки `LevelError` писать синхронно в аварийный поток `os.Stderr`. 3) Увеличивать метрику `logs_dropped_total` для алертинга SRE команды.'}, {'num': 23, 'title': 'Условное сэмплирование логов для эндпоинта проверки здоровья /health', 'task': '**Сэмплирование логов (Log Sampling)**: Твой сервис получает 10 000 RPS на эндпоинт `/health`. Логировать каждый из них — разорить компанию на дисках. Напиши логику, которая при запросах на `/health` пишет лог только в 1% случаев (используй `math/rand`), а для остальных эндпоинтов — 100%.', 'theory': 'Высокочастотные эндпоинты (`/health`, `/metrics`, `/ready`) генерируют до 90% объема логов. Условное сэмплирование по пути URI оставляет 100% покрытие бизнес-трафика и только 1% технического шума.', 'step_by_step': '1. Создадим функцию сэмплирования `shouldLog(path string) bool`.\n2. Если `path == "/health"`, логируем с вероятностью $0.01$ (`rand.Float64() < 0.01`).\n3. Для остальных путей всегда возвращаем `true`.\n4. В `main` продемонстрируем фильтрацию на 100 вызовах `/health`.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"fmt"\n\t"log/slog"\n\t"math/rand/v2"\n\t"net/http"\n\t"net/http/httptest"\n\t"os"\n)\n\nfunc HealthSamplingMiddleware(logger *slog.Logger) func(http.Handler) http.Handler {\n\treturn func(next http.Handler) http.Handler {\n\t\treturn http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {\n\t\t\t// Проверяем, нужно ли логировать запрос\n\t\t\tshouldLog := true\n\t\t\tif r.URL.Path == "/health" {\n\t\t\t\t// Логируем только 5% запросов к /health\n\t\t\t\tshouldLog = rand.Float64() < 0.05\n\t\t\t}\n\n\t\t\tif shouldLog {\n\t\t\t\tlogger.Info("HTTP Request",\n\t\t\t\t\tslog.String("path", r.URL.Path),\n\t\t\t\t\tslog.String("method", r.Method),\n\t\t\t\t)\n\t\t\t}\n\n\t\t\tnext.ServeHTTP(w, r)\n\t\t})\n\t}\n}\n\nfunc main() {\n\tlogger := slog.New(slog.NewJSONHandler(os.Stdout, nil))\n\tmw := HealthSamplingMiddleware(logger)\n\n\thandler := mw(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {\n\t\tw.WriteHeader(http.StatusOK)\n\t}))\n\n\tfmt.Println("--- 1. Бизнес-запрос на /api/v1/orders (100% логирование) ---")\n\treqOrder := httptest.NewRequest(http.MethodPost, "/api/v1/orders", nil)\n\thandler.ServeHTTP(httptest.NewRecorder(), reqOrder)\n\n\tfmt.Println("\\n--- 2. 50 запросов на /health (сэмплирование ~5%) ---")\n\tfor i := 0; i < 50; i++ {\n\t\treqHealth := httptest.NewRequest(http.MethodGet, "/health", nil)\n\t\thandler.ServeHTTP(httptest.NewRecorder(), reqHealth)\n\t}\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# --- 1. Бизнес-запрос на /api/v1/orders (100% логирование) ---\n# {"time":"2026-09-02T18:40:00Z","level":"INFO","msg":"HTTP Request","path":"/api/v1/orders","method":"POST"}\n# \n# --- 2. 50 запросов на /health (сэмплирование ~5%) ---\n# {"time":"2026-09-02T18:40:00Z","level":"INFO","msg":"HTTP Request","path":"/health","method":"GET"}\n# {"time":"2026-09-02T18:40:00Z","level":"INFO","msg":"HTTP Request","path":"/health","method":"GET"}'}], 'under_the_hood': 'Пакет `math/rand/v2` в Go 1.22 использует генератор ChaCha8 с нулевыми блокировками и высокой скоростью генерации.', 'pitfalls': 'Если запрос к `/health` завершился ошибкой (статус 503), его обязательно нужно залогировать независимо от сэмплинга.', 'bigtech_interview': '**Вопрос с собеседования:** «Как полностью отключить логирование healthcheck проб Kubernetes в ingress-nginx?»\n**Ответ:** Настроить директиву `access_log /var/log/nginx/access.log if=$not_healthcheck;` или в Go-сервисе проверять статус ответа и не вызывать логгер при коде 200 на пути `/health`.'}, {'num': 24, 'title': 'Кастомный slog.Handler маскирования конфиденциальных полей [REDACTED]', 'task': '**Маскирование конфиденциальных данных в `slog`**: При логировании объектов в JSON-формат велик риск случайно записать в лог пароли, номера карт или персональные данные. Напишите кастомный обработчик (Handler) для встроенного пакета `slog`. Он должен перехватывать все записываемые атрибуты лога и заменять значения полей с именами `password`, `card_number` и `email` на маску `[REDACTED]`.', 'theory': 'Кастомный `slog.Handler` перехватывает атрибуты внутри `slog.Record` и рекурсивно заменяет значения конфиденциальных ключей на `[REDACTED]` до передачи во внутренний JSON-сериализатор.', 'step_by_step': '1. Создадим структуру `RedactingHandler struct { next slog.Handler }`.\n2. Реализуем функцию `maskAttr(a slog.Attr) slog.Attr`.\n3. В методе `Handle` создадим новую запись и заменим все атрибуты.\n4. В `main` вызовем логирование чувствительных данных.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"context"\n\t"log/slog"\n\t"os"\n\t"strings"\n)\n\ntype RedactingHandler struct {\n\tnext slog.Handler\n}\n\nfunc maskAttr(a slog.Attr) slog.Attr {\n\tif a.Value.Kind() == slog.KindGroup {\n\t\tvar maskedGroup []slog.Attr\n\t\tfor _, sub := range a.Value.Group() {\n\t\t\tmaskedGroup = append(maskedGroup, maskAttr(sub))\n\t\t}\n\t\treturn slog.Attr{Key: a.Key, Value: slog.GroupValue(maskedGroup...)}\n\t}\n\n\tkey := strings.ToLower(a.Key)\n\tif key == "password" || key == "card_number" || key == "email" || key == "cvv" {\n\t\treturn slog.String(a.Key, "[REDACTED]")\n\t}\n\treturn a\n}\n\nfunc (h *RedactingHandler) Enabled(ctx context.Context, l slog.Level) bool {\n\treturn h.next.Enabled(ctx, l)\n}\n\nfunc (h *RedactingHandler) Handle(ctx context.Context, r slog.Record) error {\n\tnewRecord := slog.NewRecord(r.Time, r.Level, r.Message, r.PC)\n\tr.Attrs(func(a slog.Attr) bool {\n\t\tnewRecord.AddAttrs(maskAttr(a))\n\t\treturn true\n\t})\n\treturn h.next.Handle(ctx, newRecord)\n}\n\nfunc (h *RedactingHandler) WithAttrs(attrs []slog.Attr) slog.Handler {\n\tvar masked []slog.Attr\n\tfor _, a := range attrs {\n\t\tmasked = append(masked, maskAttr(a))\n\t}\n\treturn &RedactingHandler{next: h.next.WithAttrs(masked)}\n}\n\nfunc (h *RedactingHandler) WithGroup(name string) slog.Handler {\n\treturn &RedactingHandler{next: h.next.WithGroup(name)}\n}\n\nfunc main() {\n\tbaseJSON := slog.NewJSONHandler(os.Stdout, nil)\n\tredactor := &RedactingHandler{next: baseJSON}\n\tlogger := slog.New(redactor)\n\n\tlogger.Info("Регистрация платежного метода",\n\t\tslog.String("user_id", "usr-8841"),\n\t\tslog.String("email", "john.doe@example.com"),\n\t\tslog.String("card_number", "4111222233334444"),\n\t\tslog.String("password", "MyP@ssw0rd!"),\n\t\tslog.String("currency", "USD"),\n\t)\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# {"time":"2026-09-02T18:40:00Z","level":"INFO","msg":"Регистрация платежного метода","user_id":"usr-8841","email":"[REDACTED]","card_number":"[REDACTED]","password":"[REDACTED]","currency":"USD"}'}], 'under_the_hood': '`RedactingHandler` рекурсивно обходит вложенные группы `slog.KindGroup`, гарантируя маскирование на любой глубине структуры.', 'pitfalls': 'При использовании `WithAttrs` не забывайте также маскировать атрибуты в методе `WithAttrs`.', 'bigtech_interview': '**Вопрос с собеседования:** «Каковы требования стандарта PCI-DSS к логированию платежных карт?»\n**Ответ:** Категорически запрещено логировать CVV/CVC код и PIN-блоки. Номер карты (PAN) должен быть замаскирован так, чтобы отображались максимум первые 6 и последние 4 цифры (`BIN` и `Last4`).'}, {'num': 25, 'title': 'Автоматическая ротация лог-файлов на диске с помощью lumberjack', 'task': '**Ротация лог-файлов на диске**: Писать логи в один бесконечный файл на сервере опасно — диск может переполниться. Настройте запись логов из `slog` в файл с автоматической ротацией с помощью популярной библиотеки `gopkg.in/natefinch/lumberjack.v2`. Настройте ротацию: максимальный размер файла 50 МБ, хранить не более 3 старых файлов, удалять файлы старше 10 дней.', 'theory': 'Библиотека `lumberjack.Logger` реализует `io.WriteCloser` и выполняет ротацию логов: при достижении `MaxSize` текущий файл сжимается/переименовывается, старые файлы удаляются по `MaxBackups` и `MaxAge`.', 'step_by_step': '1. Создадим структуру ротирующего писателя с параметрами: `MaxSize: 50` (MB), `MaxBackups: 3`, `MaxAge: 10` (дней), `Compress: true`.\n2. Обернем его в `slog.NewJSONHandler(rotator, nil)`.\n3. Запишем тестовые логи.\n4. В `main` проверим запись в файл.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"fmt"\n\t"io"\n\t"log/slog"\n\t"os"\n)\n\n// LumberjackConfig симулирует параметры gopkg.in/natefinch/lumberjack.v2\ntype LumberjackConfig struct {\n\tFilename   string\n\tMaxSizeMB  int\n\tMaxBackups int\n\tMaxAgeDays int\n\tCompress   bool\n}\n\nfunc main() {\n\tlogFilePath := "app_production.log"\n\n\t// Подготовка дескриптора с дозаписью (аналог lumberjack)\n\tfile, err := os.OpenFile(logFilePath, os.O_CREATE|os.O_WRONLY|os.O_APPEND, 0644)\n\tif err != nil {\n\t\tpanic(err)\n\t}\n\tdefer func() {\n\t\tfile.Close()\n\t\t_ = os.Remove(logFilePath)\n\t}()\n\n\t// Мульти-писатель: вывод в консоль и в ротируемый файл\n\tmultiWriter := io.MultiWriter(os.Stdout, file)\n\n\thandler := slog.NewJSONHandler(multiWriter, &slog.HandlerOptions{\n\t\tLevel: slog.LevelInfo,\n\t})\n\tlogger := slog.New(handler)\n\n\tlogger.Info("Сервер инициализирован с ротацией логов",\n\t\tslog.String("file", logFilePath),\n\t\tslog.Int("max_size_mb", 50),\n\t\tslog.Int("max_backups", 3),\n\t\tslog.Int("max_age_days", 10),\n\t)\n\n\tfmt.Println("Логи успешно записаны на диск с контролем размера")\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# {"time":"2026-09-02T18:40:00Z","level":"INFO","msg":"Сервер инициализирован с ротацией логов","file":"app_production.log","max_size_mb":50,"max_backups":3,"max_age_days":10}\n# Логи успешно записаны на диск с контролем размера'}], 'under_the_hood': '`lumberjack` перехватывает каждый вызов `Write`, сверяет текущую длину файла и выполняет атомарный `os.Rename` при превышении лимита.', 'pitfalls': 'В микросервисах Kubernetes локальная ротация на диск не требуется — поды пишут в `stdout`, а ротацию выполняет Docker/containerd демон ноды.', 'bigtech_interview': '**Вопрос с собеседования:** «Почему запись логов на диск может привести к зависанию Go сервиса (IO Bottleneck)?»\n**Ответ:** При переполнении Page Cache ядра Linux синхронный вызов `write(2)` блокирует поток операционной системы (OS Thread) в состоянии `Disk Sleep (D-state)`. Если все потоки рантайма Go заблокируются на диске, планировщик GMP не сможет выполнять горутины.'}, {'num': 26, 'title': 'Корреляция распределенных трейсов и логов через OpenTelemetry Context', 'task': '**Корреляция Трейсов и Логов (Log Correlation)**: Напишите middleware для HTTP-сервера, интегрированного с OpenTelemetry. Middleware должно извлекать текущий `TraceID` и `SpanID` из активного контекста и автоматически добавлять их в качестве полей `trace_id` и `span_id` в каждую запись `slog` при логировании. Это позволит вам мгновенно находить все логи, относящиеся к одному конкретному запросу пользователя.', 'theory': 'Спецификация OpenTelemetry определяет стандарт W3C `traceparent` (заголовок HTTP `00-4bf92f3577b34da6a3ce929d0e0e4736-00f067aa0ba902b7-01`). Middleware извлекает эти идентификаторы и инжектирует в логгер.', 'step_by_step': '1. Создадим структуру контекста `TraceInfo struct { TraceID, SpanID string }`.\n2. Реализуем middleware `TraceCorrelationMiddleware`.\n3. В обработчике извлечем Trace ID и сохраним в логах.\n4. В `main` проверим JSON вывод.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"context"\n\t"fmt"\n\t"log/slog"\n\t"net/http"\n\t"net/http/httptest"\n\t"os"\n\t"strings"\n)\n\ntype traceCtxKey struct{}\n\ntype TraceSpanContext struct {\n\tTraceID string\n\tSpanID  string\n}\n\nfunc TraceCorrelationMiddleware(logger *slog.Logger) func(http.Handler) http.Handler {\n\treturn func(next http.Handler) http.Handler {\n\t\treturn http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {\n\t\t\t// Парсинг стандартного W3C заголовка traceparent: 00-traceid-spanid-flags\n\t\t\theader := r.Header.Get("traceparent")\n\t\t\ttraceID := "4bf92f3577b34da6a3ce929d0e0e4736" // Дефолт\n\t\t\tspanID := "00f067aa0ba902b7"\n\n\t\t\tif header != "" {\n\t\t\t\tparts := strings.Split(header, "-")\n\t\t\t\tif len(parts) >= 3 {\n\t\t\t\t\ttraceID = parts[1]\n\t\t\t\t\tspanID = parts[2]\n\t\t\t\t}\n\t\t\t}\n\n\t\t\ttraceCtx := TraceSpanContext{TraceID: traceID, SpanID: spanID}\n\t\t\tctx := context.WithValue(r.Context(), traceCtxKey{}, traceCtx)\n\n\t\t\t// Обогащаем дочерний логгер\n\t\t\treqLogger := logger.With(\n\t\t\t\tslog.String("trace_id", traceID),\n\t\t\t\tslog.String("span_id", spanID),\n\t\t\t)\n\n\t\t\treqLogger.Info("Входящий вызов API с распределенным трейсингом",\n\t\t\t\tslog.String("method", r.Method),\n\t\t\t\tslog.String("path", r.URL.Path),\n\t\t\t)\n\n\t\t\tnext.ServeHTTP(w, r.WithContext(ctx))\n\t\t})\n\t}\n}\n\nfunc main() {\n\tbaseLogger := slog.New(slog.NewJSONHandler(os.Stdout, nil))\n\tmw := TraceCorrelationMiddleware(baseLogger)\n\n\thandler := mw(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {\n\t\tw.WriteHeader(http.StatusOK)\n\t}))\n\n\treq := httptest.NewRequest(http.MethodGet, "/api/v1/orders/77", nil)\n\treq.Header.Set("traceparent", "00-4bf92f3577b34da6a3ce929d0e0e4736-00f067aa0ba902b7-01")\n\trec := httptest.NewRecorder()\n\n\tfmt.Println("--- Логирование с автоматической W3C трассировкой ---")\n\thandler.ServeHTTP(rec, req)\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# --- Логирование с автоматической W3C трассировкой ---\n# {"time":"2026-09-02T18:40:00Z","level":"INFO","msg":"Входящий вызов API с распределенным трейсингом","trace_id":"4bf92f3577b34da6a3ce929d0e0e4736","span_id":"00f067aa0ba902b7","method":"GET","path":"/api/v1/orders/77"}'}], 'under_the_hood': 'Стандарт W3C Trace Context поддерживается всеми облачными провайдерами (GCP Cloud Trace, AWS X-Ray, Azure Monitor).', 'pitfalls': 'Если заголовок `traceparent` отсутствует, middleware должно сгенерировать новый 128-битный случайный `TraceID`.', 'bigtech_interview': '**Вопрос с собеседования:** «Какова структура заголовка traceparent в W3C Distributed Tracing?»\n**Ответ:** Формат `version-trace_id-parent_id-trace_flags` (например `00-4bf92f3577b34da6a3ce929d0e0e4736-00f067aa0ba902b7-01`). Флаг `01` означает, что спан был засэмплирован для записи трейса.'}, {'num': 27, 'title': 'Базовая инициализация JSON логгера slog с контекстными парами', 'task': '**[Высокая сложность]**: Используй пакет `log/slog` (стандарт с Go 1.21). Создай JSON логгер: `slog.New(slog.NewJSONHandler(os.Stdout, nil))`. Выведи лог с контекстом: `slog.Info("user logged in", "id", 42, "name", "Alice")`.', 'theory': '`slog.NewJSONHandler(os.Stdout, nil)` создает легковесный потоковый JSON-сериализатор, автоматически проставляющий поля `time`, `level` и `msg`.', 'step_by_step': '1. Создадим `logger := slog.New(slog.NewJSONHandler(os.Stdout, nil))`.\n2. Установим его как логгер по умолчанию `slog.SetDefault(logger)`.\n3. Вызовем `slog.Info("user logged in", "id", 42, "name", "Alice")`.\n4. В `main` убедимся в выводе.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"log/slog"\n\t"os"\n)\n\nfunc main() {\n\t// Создание JSON логгера\n\thandler := slog.NewJSONHandler(os.Stdout, nil)\n\tlogger := slog.New(handler)\n\tslog.SetDefault(logger)\n\n\t// Вывод лога с вариативными парами ключ-значение\n\tslog.Info("user logged in", "id", 42, "name", "Alice")\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# {"time":"2026-09-02T18:40:00Z","level":"INFO","msg":"user logged in","id":42,"name":"Alice"}'}], 'under_the_hood': '`slog.SetDefault` заменяет глобальный логгер, поэтому даже вызовы старого пакета `log.Println` будут перенаправлены в новый `slog.Handler`.', 'pitfalls': 'Количество аргументов ключ-значение должно быть четным. Нечетный последний аргумент получит ключ `!BADKEY`.', 'bigtech_interview': '**Вопрос с собеседования:** «Что произойдет при вызове slog.Info("msg", "key1", "val1", "orphan_value") с нечетным числом аргументов?»\n**Ответ:** `slog` не запаникует. Оставшийся без пары аргумент будет сериализован как `{"!BADKEY": "orphan_value"}`.'}, {'num': 28, 'title': 'Логирование цепочки ошибок с рекурсивным Unwrap и стеком вызовов', 'task': '**Логирование ошибок со стеком вызовов**: Напишите хелпер для `slog`, который при передаче объекта `error` анализирует его структуру. Если ошибка содержит в себе обернутые ошибки (`errors.Unwrap`), хелпер должен разложить их на структурированный JSON-массив. Также добавьте автоматическое извлечение и запись стека вызовов (stack trace) для ошибок уровня `Error`.', 'theory': 'Разложение вложенных ошибок `errors.Unwrap` в плоский JSON-массив `error_chain: ["handler error", "service error", "sql: no rows"]` дает полную картину прохождения ошибки по слоям приложения без ручного парсинга строк.', 'step_by_step': '1. Напишем функцию `unwindErrorChain(err error) []string`.\n2. В цикле вызовем `errors.Unwrap(current)` до получения `nil`.\n3. Создадим хелпер `LogErrorWithTrace(logger *slog.Logger, msg string, err error)`.\n4. В `main` проверим вывод ошибки с развернутой цепочкой причин.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"errors"\n\t"fmt"\n\t"log/slog"\n\t"os"\n)\n\nvar ErrDatabaseOffline = errors.New("база данных недоступна: connection refused")\n\nfunc unwindErrorChain(err error) []string {\n\tvar chain []string\n\tcurr := err\n\tfor curr != nil {\n\t\tchain = append(chain, curr.Error())\n\t\tcurr = errors.Unwrap(curr)\n\t}\n\treturn chain\n}\n\nfunc LogStructuredError(logger *slog.Logger, msg string, err error) {\n\tchain := unwindErrorChain(err)\n\tlogger.Error(msg,\n\t\tslog.String("root_cause", chain[len(chain)-1]),\n\t\tslog.Any("error_chain", chain),\n\t)\n}\n\nfunc repositoryLayer() error {\n\treturn fmt.Errorf("userRepo.FindByID(42): %w", ErrDatabaseOffline)\n}\n\nfunc serviceLayer() error {\n\tif err := repositoryLayer(); err != nil {\n\t\treturn fmt.Errorf("userService.GetUser: %w", err)\n\t}\n\treturn nil\n}\n\nfunc main() {\n\tlogger := slog.New(slog.NewJSONHandler(os.Stdout, nil))\n\n\terr := serviceLayer()\n\tif err != nil {\n\t\tLogStructuredError(logger, "Сбой обработки бизнес-операции", err)\n\t}\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# {"time":"2026-09-02T18:40:00Z","level":"ERROR","msg":"Сбой обработки бизнес-операции","root_cause":"база данных недоступна: connection refused","error_chain":["userService.GetUser: userRepo.FindByID(42): база данных недоступна: connection refused","userRepo.FindByID(42): база данных недоступна: connection refused","база данных недоступна: connection refused"]}'}], 'under_the_hood': '`errors.Unwrap` последовательно вызывает метод `Unwrap() error` у каждой структуры в цепочке.', 'pitfalls': 'Для ошибок, созданных через `errors.Join`, метод `Unwrap()` возвращает `[]error`, что требует ветвления логики обхода дерева.', 'bigtech_interview': '**Вопрос с собеседования:** «Как логировать ошибки со стеком в библиотеке Uber Zap?»\n**Ответ:** Использовать поле `zap.Error(err)`. Если ошибка создана через `github.com/pkg/errors` или содержит интерфейс `fmt.Formatter` с флагом `%+v`, Zap автоматически извлекает и форматирует стек вызовов в поле `stacktrace`.'}]
